from __future__ import annotations

import asyncio
import datetime as dt

import pytest
from ds.ai import extract
from pydantic import BaseModel, ValidationError
from pydantic_ai_harness.playwright import PlaywrightBrowser


class DailyClose(BaseModel):
    date: dt.date
    close: float


GOOD = """
def parse(body):
    return [DailyClose(date=date(*row[0]), close=row[1]) for row in json.loads(body)]
"""


def test_a_plain_parser_runs_and_its_rows_are_validated():
    rows = extract.run_parser(GOOD, "[[[2025,11,17],267.46],[[2025,11,18],267.44]]", list[DailyClose])
    assert rows == [
        DailyClose(date=dt.date(2025, 11, 17), close=267.46),
        DailyClose(date=dt.date(2025, 11, 18), close=267.44),
    ]


@pytest.mark.parametrize(
    ("code", "why"),
    [
        ("def parse(body):\n    import os\n    return []", "import"),
        ("def parse(body):\n    return open('/etc/passwd').read()", "open"),
        ("def parse(body):\n    return eval(body)", "eval"),
        ("def parse(body):\n    return getattr(json, 'loads')(body)", "getattr"),
        ("def parse(body):\n    return ().__class__.__base__.__subclasses__()", "dunder"),
        ("def parse(body):\n    return __builtins__", "__builtins__"),
        ("x = 1", "must define"),
        ("def parse(body) return", "not valid Python"),
    ],
)
def test_unsafe_parsers_are_refused_before_running(code: str, why: str):
    assert why in extract.parser_problem(code)
    with pytest.raises(ValueError, match="parser refused"):
        extract.run_parser(code, "[]", list[DailyClose])


@pytest.mark.parametrize("back_door", ["json.codecs.open('/etc/passwd')", "re.enum.sys.modules", "datetime.sys"])
def test_parser_modules_are_stand_ins_without_back_doors(back_door: str):
    """The real json / re reach other modules through their attributes; a parser's can't."""
    code = f"def parse(body):\n    return {back_door}"
    assert extract.parser_problem(code) == ""  # nothing the syntax check can see
    with pytest.raises(AttributeError):
        extract.run_parser(code, "[]", list[DailyClose])


def test_a_parsers_wrong_rows_fail_validation():
    with pytest.raises(ValidationError):
        extract.run_parser("def parse(body):\n    return [{'date': 'x', 'close': 1}]", "", list[DailyClose])


def test_html_becomes_markdown_with_tables_and_without_scripts():
    html = """<html><head><script>var secret = 1;</script><style>p{}</style></head><body>
    <h1>Aerials</h1><table><tr><th>Move</th><th>Startup</th></tr><tr><td>Nair</td><td>4</td></tr></table>
    <svg><path d="M0 0"/></svg></body></html>"""
    text = extract._html_to_markdown(html)
    assert "# Aerials" in text
    assert "| Nair | 4 |" in text
    assert "secret" not in text
    assert "path" not in text


@pytest.mark.parametrize(
    ("url", "why"),
    [
        ("file:///etc/passwd", "isn't an http(s) URL"),
        ("http://localhost:8000/ping", "local or private"),
        ("http://127.0.0.1:3000", "local or private"),
        ("http://192.168.1.1/", "local or private"),
    ],
)
def test_only_public_http_urls_are_read(url: str, why: str):
    assert why in extract.url_problem(url)


def test_the_report_says_what_was_done():
    report = extract.FromUrlReport(
        url="https://example.com",
        how="parsed",
        path="browser",
        steps=["navigate: https://example.com", "click: 1Y"],
        parse_attempts=[("def parse(body): ...", "error: KeyError"), (GOOD, "2 rows")],
        parse_code=GOOD,
        rows=2,
        cost=0.03,
        seconds=40,
    )
    assert report.summary() == " ".join(
        [
            "from_url (https://example.com): browser, clicked 1Y,",
            "parsed by an AI-written parser (2 tries), 2 rows, 40 s, $0.030",
        ]
    )
    detail = report.detail()
    assert "2. click: 1Y" in detail
    assert "Parser try 1 -> error: KeyError" in detail
    assert "Parser that made the value:" in detail


def test_the_harness_still_has_the_page_our_recorder_reads():
    """_browse reads the run's page from a private attribute: fail if an update moves it."""
    session = PlaywrightBrowser()._session
    assert hasattr(session, "page")
    assert callable(getattr(PlaywrightBrowser, "for_run", None))


def test_a_value_labelled_only_by_its_class_keeps_the_label():
    """A site whose numbers are bare divs named by class: without the label the AI guesses."""
    html = '<div class="movename">Back Air</div><div class="landinglag">16</div><div class="advantage">-13</div>'
    text = extract._html_to_markdown(html)
    assert "landinglag: 16" in text
    assert "advantage: -13" in text


def test_an_ai_failure_on_the_quick_path_is_raised_and_no_browser_starts(monkeypatch):
    """Only a failed download falls back to the browser: a failed AI call (eg no credits)
    would fail there too, after starting Chromium for nothing.
    """
    from pydantic_ai.exceptions import ModelQuotaExceededError

    async def no_credits(*_args, **_kwargs):
        raise ModelQuotaExceededError("claude-haiku-5-5", "402", body={"detail": "no credits"})

    async def browser(*_args, **_kwargs):
        raise AssertionError("the browser was started")

    monkeypatch.setattr(
        extract, "page_text", lambda url: extract.PageText(url=url, kind="html", text="x", truncated=False)
    )
    monkeypatch.setattr(extract, "_copy", no_credits)
    monkeypatch.setattr(extract, "_browse", browser)
    with pytest.raises(ModelQuotaExceededError):
        asyncio.run(extract.afrom_url("https://example.com", int))
